async function routeByIds(){if(feedbackPolling||!routePending||Date.now()<routeRetryAt||routeBusy||wizardActive||playing||enrollActive||enrollStarting||calibration.state().busy||(root.pianoFirmwareBusy?.()||(root.pianoMountBusy?.()||root.pianoValidationBusy?.()))||root.pianoStrictTrainingActive?.())return;const state=root.PianoDeliveryHooks.getState();if(!state.connected||state.playing)return;routeBusy=true;const identity=state.identity;try{const infoLines=await root.PianoDeliveryHooks.send('INFO',650,25),info=fields(infoLines.find(l=>/^OK INFO /.test(l))||'');if(!info.armed){showView('demoEnrollment');el('demoEnrollStatus').textContent='正在实时检测六台舵机…';lastScanIds=null;lastComplete=null;onlineReady=false;calibration.invalidateOnline();paint();routePending=true;routeRetryAt=Date.now()+2500;return;}if(info.enroll_active==='1'){showView('demoEnrollment');lastScanIds=null;onlineReady=false;await readEnroll();return;}if(info.armed!=='0'||info.auto_active!=='0'||info.enroll_active!=='0'||info.sweep!=='0')return;const lines=await root.PianoDeliveryHooks.send('SCAN',1400,500);if(root.PianoDeliveryHooks.getState().identity!==identity)return;if(!lines.some(l=>/^SCAN_END count=\d+$/.test(l)))throw Error('扫描未完成');const complete=completeIds(lines);lastScanIds=lines.filter(l=>/^FOUND id=\d+$/.test(l)).map(l=>Number(fields(l).id));onlineReady=complete;if(!complete)calibration.invalidateOnline();paint();const needHydrate=complete&&(lastComplete!==true||routeIdentity!==identity||forceCalibration);routePending=forceCalibration&&!complete;routeRetryAt=Date.now()+2500;routeIdentity=identity;if(lastComplete!==complete||(complete&&forceCalibration)){showView(complete?'demoCalibration':'demoEnrollment');lastComplete=complete;if(complete)forceCalibration=false;}if(needHydrate&&!(calibration.state().samples.some(v=>v&&!v.persisted)&&!calibration.state().saved&&!calibration.state().savedBeforeOffline)){const loaded=await calibration.hydrate();const outside=[...new Set([...(calibration.state().outsideSlots||[]),...calibration.state().samples.flatMap((v,i)=>v?.qualityRejected?[i]:[])])],wrapped=calibration.state().samples.some(v=>v?.range&&v.range.min>v.range.max);if(outside.length){pendingRepairSlots=outside;el('demoRepairCalibration').textContent='补校准'+outside.map(n=>names[n]).join('、');}paint();el('demoActionMessage').textContent=outside.length?outside.map(n=>names[n]).join('、')+'超出记录范围，请补校准。':loaded&&wrapped?'记录已保存；食指跨零行程的主动动作暂未启用。':loaded?'点击单指、组合或交替。':'请先完成校准。';el('demoCalibrationGuide').textContent=pendingRepairSlots.length?pendingRepairSlots.map(n=>names[n]).join('、')+'需要补校准':loaded&&wrapped?'6 根校准记录已保存':loaded?'6 台已校准，可以开始展示':'6 台已编号，请开始校准';el('demoCalStart').textContent='全部重新校准';el('demoCalibrationProgress').textContent=pendingRepairSlots.length?'其余记录已保留。完整往返一次，最后自然放松。':loaded&&wrapped?'食指行程跨零，需核对安装角度后再展示动作。':loaded?'已核对保存记录与当前位置。':'完整往返一次，最后自然放松。';document.querySelectorAll('.demoCalSlot').forEach(n=>{const needs=pendingRepairSlots.includes(Number(n.dataset.slot));n.classList.toggle('done',loaded&&!needs);n.classList.toggle('current',needs);});}if(!enrollView.hidden&&!complete)await readEnroll();}catch(e){lastScanIds=null;lastComplete=null;onlineReady=false;calibration.invalidateOnline();paint();document.querySelectorAll('.demoEnrollSlot').forEach(n=>{n.classList.remove('done','current');n.querySelector('small').textContent='重新检测';});routePending=true;routeRetryAt=Date.now()+2500;showView('demoEnrollment');el('demoEnrollStatus').textContent='正在重新确认六台舵机，请保持接线。';}finally{routeBusy=false;}}
document.addEventListener('delivery:state',()=>routeByIds());setInterval(()=>{routePending=true;routeByIds();},10000);routeByIds();
el('demoEnrollStop').onclick=async()=>{try{const lines=await root.PianoDeliveryHooks.send('ENROLL STOP');if(!lines.some(l=>/^OK ENROLL STOP(?: |$)/.test(l)))throw Error('停止编号未确认');await stop();enrollActive=false;el('demoEnrollStatus').textContent='已停止编号。';}catch(e){el('demoEnrollStatus').textContent=e.message;}};
const levelHistory=Array(6).fill(null);
function updateLevels(rows,hardware){for(const row of rows){const slot=Number(row.slot),pos=Number(row.pos),card=document.querySelector(`#demoCalibrationSlots [data-slot="${slot}"]`);if(!card||row.online!=='1'||!Number.isInteger(pos)||pos<0||pos>hardware.range)continue;let h=levelHistory[slot];if(!h||h.range!==hardware.range){const saved=calibration.state().samples[slot]?.range;h=levelHistory[slot]={last:pos,total:pos,origin:pos,low:saved?.min??pos,high:saved?(saved.max<saved.min?saved.max+hardware.range+1:saved.max):pos,range:hardware.range};}h.total+=circularDelta(h.last,pos,hardware.range);h.last=pos;h.low=Math.min(h.low,h.total);h.high=Math.max(h.high,h.total);const recorded=calibration.state().samples[slot]?.range;if(!wizardActive&&recorded){h.low=recorded.min;h.high=recorded.max<recorded.min?recorded.max+hardware.range+1:recorded.max;card.classList.toggle('outside',!feedbackNearArc(recorded.min,recorded.max,pos,hardware.range));}else card.classList.remove('outside');const n=hardware.range+1,norm=x=>((x%n)+n)%n,low=norm(h.low),high=norm(h.high),span=h.high-h.low,wrap=low>high,full=span>=n;card.style.setProperty('--cursor-level',(100*pos/hardware.range)+'%');card.style.setProperty('--sweep-bottom',(full?0:100*low/hardware.range)+'%');card.style.setProperty('--sweep-height',(full?100:wrap?100-100*low/hardware.range:100*(high-low)/hardware.range)+'%');card.style.setProperty('--wrap-height',(!full&&wrap?100*high/hardware.range:0)+'%');card.querySelector('.demoScaleMax').textContent=hardware.range;card.querySelector('.demoPosition').textContent='位置 '+pos;card.querySelector('.demoDelta').textContent=(!wizardActive&&calibration.state().samples[slot]?.qualityRejected?'旧范围（无效） ':'已扫 ')+low+'～'+high+(wrap?'（跨零）':'');}if(!wizardActive&&!playing&&calibration.state().saved&&rows.length===6){const samples=calibration.state().samples;pendingRepairSlots=rows.filter(r=>{const sample=samples[Number(r.slot)],v=sample?.range;return sample?.qualityRejected||(v&&!feedbackNearArc(v.min,v.max,Number(r.pos),hardware.range));}).map(r=>Number(r.slot));if(samples.some(v=>v?.qualityRejected)){el('demoCalibrationGuide').textContent='食指记录含异常跳变，请只重测食指';el('demoCalibrationProgress').textContent='另外五路已保留。完整往返一次，最后自然放松。';el('demoActionMessage').textContent='先重测食指。';}else if(pendingRepairSlots.length){el('demoCalibrationGuide').textContent='校准已保留，请让手指回到红色范围内';el('demoCalibrationProgress').textContent=pendingRepairSlots.map(i=>names[i]).join('、')+'当前位置超出记录范围';el('demoActionMessage').textContent='轻轻回到红色范围内，遇到阻力停止。';}else if(!playing){el('demoCalibrationGuide').textContent='6 台已校准，可以开始展示';el('demoCalibrationProgress').textContent='已核对保存记录与当前位置。';}paint();}}
const idleFeedback=idleFeedbackReader({getState:root.PianoDeliveryHooks.getState,getRange:()=>calibration.state().samples.find(v=>v)?.encoderRange||root.PianoDeliveryHooks.getState().info?.range,send:root.PianoDeliveryHooks.send,onFeedback:(rows,meta)=>{const node=el('demoCalibrationSlots');if(node){node.dataset.feedbackCount=String(Number(node.dataset.feedbackCount||0)+1);node.dataset.feedbackTime=String(Date.now());}updateLevels(rows,meta);},onUnavailable:()=>{routePending=true;routeRetryAt=0;lastComplete=null;onlineReady=false;calibration.invalidateOnline();paint();}});
setInterval(async()=>{if(feedbackPolling||routeBusy||routePending||enrollPolling||root.deliveryDemoBusy()||(root.pianoFirmwareBusy?.()||(root.pianoMountBusy?.()||root.pianoValidationBusy?.()))||!onlineReady||el('demoCalibration').hidden)return;feedbackPolling=true;try{await idleFeedback.tick();}finally{feedbackPolling=false;if(routePending)routeByIds();}},80);
let wizardStep=0,wizardStarted=false,repairQueue=null,wizardRun=null,restartPending=false;
document.addEventListener('delivery:mount-complete',()=>{showView('demoCalibration');el('demoCalibrationGuide').textContent='中位安装完成，请穿戴后校准行程';el('demoCalibrationProgress').textContent='点击全部重新校准，每根手指完整往返一次。';el('demoCalStart').focus();});
