document.addEventListener('delivery:calibration-reload',async event=>{try{await calibration.hydrate();pendingRepairSlots=calibration.state().outsideSlots||[];levelHistory.fill(null);paint();el('demoCalibrationGuide').textContent='6 台校准已更新';event.detail?.resolve(true);}catch(e){tell(e.message);event.detail?.reject(e);}});
document.addEventListener('delivery:mount-reset',()=>{wizardToken++;wizardActive=false;wizardStarted=false;wizardStep=0;repairQueue=null;pendingRepairSlots=[];calibration.reset();levelHistory.fill(null);forceCalibration=true;routePending=true;routeRetryAt=0;document.querySelectorAll('.demoCalSlot').forEach(n=>{n.classList.remove('done','current','outside');const badge=n.querySelector('.demoCycleCount');if(badge)badge.textContent='0/1';});el('demoCalibrationGuide').textContent='安装完成后，重新记录手指行程';el('demoCalibrationProgress').textContent='旧行程已作废。装好后穿戴，再完整往返一次。';paint();});
