document.addEventListener('click',e=>{if(!wizardActive)return;const n=e.target.closest('button,select,input,summary');if(n&&el('demoRoot').contains(n)&&n.id!=='demoStop'&&n.id!=='demoCalStart'){e.preventDefault();e.stopImmediatePropagation();}},true);
const recordingBacklog=[];async function persistRecording(recording){if(!recording)return;recordingBacklog.push(recording);root.PianoDeliveryDemo.pendingRecordings=recordingBacklog;try{const response=await fetch('/api/calibration/recording',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(recording)});if(!response.ok)throw Error('HTTP '+response.status);const reply=await response.json();if(reply.ok!==true||!reply.url||reply.error)throw Error(reply.error||'保存未确认');recordingBacklog.splice(recordingBacklog.indexOf(recording),1);const link=document.createElement('a');link.href=reply.url;link.target='_blank';link.rel='noopener';link.textContent=(recording.complete?'完整轨迹':'中断轨迹')+'已保存 · 查看';el('demoRecordingStatus').replaceChildren(link);}catch(error){root.deliveryDemoNotice?.('校准全过程记录尚未保存：'+error.message);el('demoRecordingStatus').textContent='全过程记录尚未保存，已暂留本页面；请勿刷新。';}}
el('demoRepairIndex').onclick=async()=>{if(root.deliveryDemoBusy()||!onlineReady||!calibration.state().saved)return;repairQueue=[2];wizardStarted=true;wizardStep=4;wizardRun=runCalibration();await wizardRun;};
el('demoRepairCalibration').onclick=async()=>{if(root.deliveryDemoBusy()||!onlineReady||!calibration.state().saved)return;repairQueue=[...pendingRepairSlots];wizardStarted=true;wizardStep=repairQueue[0]*2;wizardRun=runCalibration();await wizardRun;};
async function runCalibration(){if(root.deliveryDemoBusy()||(root.pianoFirmwareBusy?.()||(root.pianoMountBusy?.()||root.pianoValidationBusy?.())))return;wizardActive=true;paint();const token=++wizardToken;const check=()=>{if(token!==wizardToken)throw Error('本轮已停止');};el('demoCalStart').disabled=false;el('demoCalStart').textContent='全部重新校准';try{const safeReply=await root.PianoDeliveryHooks.send('SAFE',1000,180);if(!safeReply.some(l=>/^OK SAFE /.test(l)))throw Error('停止未确认，请检查连接后继续');check();await prepareCalibrationOrigin(root.PianoDeliveryHooks,{resume:wizardStarted,repair:!!repairQueue});check();if(!wizardStarted){levelHistory.fill(null);calibration.reset();document.querySelectorAll('.demoCalSlot').forEach(n=>{n.classList.remove('done','current');const badge=n.querySelector('.demoCycleCount');if(badge)badge.textContent='0/1';});wizardStep=0;wizardStarted=true;}for(const slot of (repairQueue||Array.from({length:6-Math.floor(wizardStep/2)},(_,i)=>i+Math.floor(wizardStep/2)))){check();wizardStep=slot*2;levelHistory[slot]=null;el('demoCalibrationGuide').textContent=names[slot]+'：完整往返一次，最后自然放松';document.querySelectorAll('.demoCalSlot').forEach(n=>{n.classList.toggle('done',!!calibration.state().samples[Number(n.dataset.slot)]?.range&&Number(n.dataset.slot)!==slot);n.classList.toggle('current',Number(n.dataset.slot)===slot);});await captureRepeated(()=>calibration.measureFast(slot),result=>calibration.commitRange(slot,result),{check,onRecording:persistRecording,onProgress:p=>{el('demoCalibrationProgress').textContent=p.phase==='prepare'?`正在记录活动 · ${p.cycles}/${p.requiredCycles||1} 次 · 实测 ${Math.round(p.hz||0)} Hz`:`第 ${slot+1}/6 步 · ${p.cycles}/${p.requiredCycles||1} 次 · ${p.phase==='direction'?'请按下再抬起，确认方向':p.phase==='finish'?'自然放松，正在记录待机位':p.phase==='back'?'抬起 → 再按下':'按下 → 抬起'} · 幅度 ${Math.round(p.measuredDegrees||0)}° / 需约 ${Math.round(p.requiredDegrees||0)}° · ${Math.round(p.hz||0)} Hz`;const card=document.querySelector(`#demoCalibrationSlots [data-slot="${slot}"] .demoCycleCount`);if(card)card.textContent=p.cycles+'/'+(p.requiredCycles||1);}});check();wizardStep=(slot+1)*2;if(repairQueue)repairQueue=repairQueue.filter(n=>n!==slot);paint();}el('demoCalibrationGuide').textContent='正在保存六槽校准…';await calibration.save();check();pendingRepairSlots=[];el('demoCalibrationGuide').textContent='校准已保存，可以开始展示';el('demoCalibrationProgress').textContent='点击右侧单指、组合或交替。';document.querySelectorAll('.demoCalSlot').forEach(n=>{n.classList.add('done');n.classList.remove('current');});el('demoQuickSingle').focus();el('demoCalStart').textContent='全部重新校准';wizardStarted=false;repairQueue=null;}catch(e){el('demoCalibrationProgress').textContent=wizardStep>=12?'六根记录已保留，保存未完成：'+e.message:e.message;if(wizardStep>=12)el('demoCalibrationGuide').textContent='动作采集完成，等待保存';el('demoCalStart').textContent='全部重新校准';}finally{wizardActive=false;el('demoCalStart').disabled=false;paint();}};

el('demoCalStart').onclick=async()=>{
 if(restartPending||playing||enrollActive||enrollStarting||root.pianoFirmwareBusy?.()||root.pianoMountBusy?.()||root.pianoValidationBusy?.())return;
 restartPending=true;
 try{
  if(wizardRun){wizardToken++;calibration.cancel();await wizardRun;}
  wizardStarted=false;wizardStep=0;repairQueue=null;pendingRepairSlots=[];
  calibration.reset();levelHistory.fill(null);forceCalibration=true;
  document.querySelectorAll('.demoCalSlot').forEach(n=>{n.classList.remove('done','current','outside');n.querySelector('.demoCycleCount').textContent='0/1';n.querySelector('.demoDelta').textContent='等待新记录';for(const key of ['--sweep-height','--wrap-height'])n.style.setProperty(key,'0%');});
  el('demoCalibrationGuide').textContent='从第一台开始重新校准';
  el('demoCalibrationProgress').textContent='本轮进度已清空';
  paint();wizardRun=runCalibration();
 }finally{restartPending=false;}
 await wizardRun;
};

